@lru_cache(maxsize=1)
def catalog():
    path = Path(__file__).parent / 'assets/reference/catalog.json'
    return json.loads(path.read_text(encoding='utf8'))

@lru_cache(maxsize=1)
def source_text():
    return (Path(__file__).parent / 'assets/reference/inference-reference.txt').read_text(encoding='utf-8-sig')

def source_entry(name):
    return next((row for row in catalog()['entries'] if row['name'] == name), None)
